using System;using System.Text;using System.IO;using System.Collections.Generic;
class MaxReference{
 static long Chars(int n,int d,int offset,int b,int zero){return n==0?zero:(long)(n/d)+((n%d+offset)/d)+b;}
 static ulong Hash(ulong h,int value){unchecked{for(int k=0;k<4;++k){h^=(byte)((uint)value>>(k*8));h*=1099511628211UL;}return h;}}
 static void Need(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(string[] args){var pages=Encoding.GetEncodings();Array.Sort(pages,delegate(EncodingInfo a,EncodingInfo b){return a.CodePage.CompareTo(b.CodePage);});long checks=0;using(var w=new StreamWriter(args[0],false,new UTF8Encoding(false))){w.WriteLine("# code_page\tbyte_multiplier\tbyte_extra\tchar_divisor\tchar_offset\tchar_extra\tchar_zero\tbyte_fnv64\tchar_fnv64");using(var edges=new StreamWriter(args[1],false,new UTF8Encoding(false))){edges.WriteLine("# code_page\tmethod\tinput\toutcome");foreach(var page in pages){var e=page.GetEncoding();int extra=e.GetMaxByteCount(0),a=e.GetMaxByteCount(1)-extra,d=0,offset=0,b=0,zero=e.GetMaxCharCount(0);for(int div=1;div<=4&&d==0;++div)for(int shift=0;shift<div&&d==0;++shift){int delta=e.GetMaxCharCount(1)-(1+shift)/div;bool good=true;for(int n=1;n<256&&good;++n)good=Chars(n,div,shift,delta,zero)==e.GetMaxCharCount(n);if(good){d=div;offset=shift;b=delta;}}Need(a>0&&d>0,"No max-count formula");ulong bh=14695981039346656037UL,ch=14695981039346656037UL;for(int n=0;n<65536;++n){int bv=e.GetMaxByteCount(n),cv=e.GetMaxCharCount(n);Need(bv==(long)n*a+extra,"Byte model mismatch");Need(cv==Chars(n,d,offset,b,zero),"Char model mismatch");bh=Hash(bh,bv);ch=Hash(ch,cv);checks+=2;}w.WriteLine(page.CodePage+"\t"+a+"\t"+extra+"\t"+d+"\t"+offset+"\t"+b+"\t"+zero+"\t"+bh.ToString("x16")+"\t"+ch.ToString("x16"));
 var inputs=new SortedSet<int>(new[]{int.MinValue,-2,-1,0,1,2,3,127,128,255,256,65535,65536,1048575,1048576,1048577,int.MaxValue,int.MaxValue-1,int.MaxValue-2});long bound=((long)int.MaxValue-extra)/a;for(int diff=-4;diff<=4;++diff){long n=bound+diff;if(n>=0&&n<=int.MaxValue)inputs.Add((int)n);}long charBound=Math.Min((long)int.MaxValue,((long)int.MaxValue-b+1)*d-offset-1);for(int diff=-4;diff<=4;++diff){long n=charBound+diff;if(n>=0&&n<=int.MaxValue)inputs.Add((int)n);}foreach(int n in inputs)for(int method=0;method<=1;++method){long model=method==0?(long)n*a+extra:Chars(n,d,offset,b,zero);try{int value=method==0?e.GetMaxByteCount(n):e.GetMaxCharCount(n);Need(n>=0&&model<=int.MaxValue&&value==model,"Boundary model mismatch");edges.WriteLine(page.CodePage+"\t"+method+"\t"+n+"\t"+value);}catch(ArgumentOutOfRangeException){Need(n<0||model>int.MaxValue,"Unexpected max-count argument exception");edges.WriteLine(page.CodePage+"\t"+method+"\t"+n+"\tArgumentOutOfRangeException");}++checks;}
 }}}Console.WriteLine(checks+" actual Framework max-count checks; all 140 default codec formulas and overflow boundaries verified");}
}